    if (!trimmedLine || trimmedLine.startsWith("#")) continue;
    const normalized = trimmedLine.toLowerCase().replace(/\s+/g, " ");
    seen.set(normalized, (seen.get(normalized) ?? 0) + 1);
  }
  for (const [normalized, count] of seen) {
    if (count > 1) {
      findings.push({
        id: `heur-${pad(hIdx++)}`, tier: "heuristics", severity: "warning",
        message: `Duplicate instruction appears ${count} times: "${normalized}"`, fixable: false,
      });
    }
  }

  // Claude-only syntax leaking into the shared AGENTS.md
  if (basename(path) === "AGENTS.md") {
    for (const marker of CLAUDE_ONLY_MARKERS) {
      if (marker.pattern.test(content)) {
        findings.push({
          id: `heur-${pad(hIdx++)}`, tier: "heuristics", severity: "warning",
          message: `Claude-only syntax (${marker.label}) found in AGENTS.md — Cursor, Codex, and Copilot won't process this`,
          fixable: false,
        });
      }
    }
  }

  if (findings.length === 0) {
    findings.push({
      id: `heur-${pad(hIdx++)}`, tier: "heuristics", severity: "pass",
      message: "no dead links, duplicate lines, or agent-specific syntax found", fixable: false,
    });
  }

  return findings;
}

export async function reviewMemoryFile(path: string, opts: ReviewOptions = {}): Promise<ReviewResult> {
  const origin = classifySkillDir(path, { cwd: opts.cwd ?? process.cwd() });
  const content = readFileSync(path, "utf-8");
  const lines = content.split("\n");
  const dir = dirname(path);
  const { config: ruleCfg, effective, ruleWarnings } = await loadReviewContext(opts.cwd ?? process.cwd());

  let sIdx = 1;
  const structFindings: ReviewFinding[] = [];

  const trimmed = content.trim();
  if (trimmed.length === 0) {
    structFindings.push({
      id: `struct-${pad(sIdx++)}`, tier: "structure", severity: "error",
      message: `${basename(path)} is empty`, fixable: false, code: "R006",
    });
  } else {
    structFindings.push({
      id: `struct-${pad(sIdx++)}`, tier: "structure", severity: "pass",
      message: `${basename(path)} is non-empty`, fixable: false, code: "R006",
    });
  }

  if (lines.length > SIZE_BUDGET_LINES) {
    structFindings.push({
      id: `struct-${pad(sIdx++)}`, tier: "structure", severity: "warning",
      message: `${lines.length} lines exceeds the ${SIZE_BUDGET_LINES}-line guidance budget for always-loaded context`,
      fixable: false, code: "R007",
    });
  } else if (trimmed.length > 0) {
    structFindings.push({
      id: `struct-${pad(sIdx++)}`, tier: "structure", severity: "pass",
      message: `within the ${SIZE_BUDGET_LINES}-line size budget (${lines.length} lines)`, fixable: false, code: "R007",
    });
  }

  let importMatch: RegExpExecArray | null;
  let importCount = 0;
  let brokenImports = 0;
  IMPORT_LINE_RE.lastIndex = 0;
  while ((importMatch = IMPORT_LINE_RE.exec(content)) !== null) {
    importCount++;
    const importPath = resolve(dir, importMatch[1]!);
    if (!existsSync(importPath)) {
      brokenImports++;
      structFindings.push({
        id: `struct-${pad(sIdx++)}`, tier: "structure", severity: "error",
        message: `@import not found: ${importMatch[1]} (resolved to ${importPath})`, fixable: false, code: "R012",
      });
    }
  }
  if (importCount > 0 && brokenImports === 0) {
    structFindings.push({
      id: `struct-${pad(sIdx++)}`, tier: "structure", severity: "pass",
      message: `${importCount} @import(s) resolved`, fixable: false, code: "R012",
    });
  }

  // Codes attached at birth — stamp once via finding.code (no English-substring map).
  const stampedStruct = structFindings
    .map((finding) => stampRule(finding, finding.code!, effective))
    .filter((finding): finding is ReviewFinding => finding !== null);
  const structTier = tallyFindings(stampedStruct);

  const heurFindings = buildHeuristicsFindings(content, path, dir)
    .map((finding) => stampRule(finding, "R019", effective))
    .filter((finding): finding is ReviewFinding => finding !== null);
  const heurTier = tallyFindings(heurFindings);

  const tiers: ReviewResult["tiers"] = { structure: structTier, heuristics: heurTier };

  if (!opts.quick) {
    const { evalCfg, agentCfg, caps, mode } = resolveJudgeContext(ruleCfg, { ci: opts.ci });
    const judgeOpts: JudgeCallOpts = { ci: opts.ci ?? false, mode };

    const principles = effective.get("R021")?.enabled
      ? loadPrinciples(opts.cwd ?? process.cwd())
      : [];
    const rubricText = buildPrincipleRubric(principles) || undefined;
    const plan = memoryLlmTierPlan(effective);
    const prompt = plan.runLint ? buildMemoryLintPrompt(content, basename(path), rubricText) : "";

    if (mode === "fail") {
      if (opts.deep) {
        throw new PrerequisiteError({
          code: "E-PRE-004",
          message: "Deep review requires an LLM judge",
        });
      }
      tiers.llm = { available: false, findings: [] };
    } else if (!plan.runLint) {
      tiers.llm = { available: false, findings: [] };
    } else if (mode === "delegate") {
      tiers.llm = { available: true, method: "delegated", prompt, findings: [] };
    } else {
      const judge = opts.memoryLintFn ?? runJudge;
      const result: LintResult = await judge(prompt, caps, agentCfg, evalCfg, judgeOpts);

      if (result.ok) {
        let lIdx = 1;
        const findings: ReviewFinding[] = [];
        for (const item of result.output.findings) {
          const code = LINT_CATEGORY_CODES[item.category];
          if (!code) continue;
          const finding = stampRule({
            id: `llm-${pad(lIdx++)}`, tier: "llm" as const, severity: item.severity,
            message: item.finding, fixable: false,
          }, code, effective);
          if (finding) findings.push(finding);
        }
        tiers.llm = { available: true, method: result.method, findings };
      } else {
        if (opts.deep) {
          throw new NetworkError({
            code: "E-NET-002",
            message: `LLM judge failed: ${result.error}`,
            suggestion: "Re-run, check the API judge credentials, or drop --deep to review without the LLM tier",
          });
        }
        tiers.llm = { available: false, findings: [] };
      }
    }
  }

  // Tier 4: session presence + binding-rule inventory; full adherence when --sessions + judge
  if (!opts.quick) {
    const loadedSess = opts.loadedSessions ?? loadRecentSessions(opts.cwd ?? process.cwd());
    if (opts.sessions && loadedSess.sessions.length === 0) {
      throw new PrerequisiteError({
        code: "E-PRE-003",
        message: "No sessions found. Use your agent, then re-run.",
      });
    }
    if (loadedSess.adaptersDetected.length === 0) {
      tiers.sessions = { available: false, findings: [] };
    } else {
      const sessFindings = [
        ...memorySessionPresence(loadedSess, { required: opts.sessions === true }),
        ...memorySessionRuleInventory(content),
      ];

      // Backlog #9: adherence uses the same judge mode owner as LLM tier.
      if (opts.sessions && loadedSess.sessions.length > 0 && effective.get("R033")?.enabled) {
        const { evalCfg, agentCfg, mode } = resolveJudgeContext(ruleCfg, { ci: opts.ci });
        if (mode === "api") {
          const newest = [...loadedSess.sessions].sort((a, b) => b.mtime - a.mtime)[0]!;
          const truncated = content.length > 12_000 ? content.slice(0, 12_000) + "\n[truncated]" : content;
          const evalFn = opts.memorySessionEvalFn ??
            ((prims, name, body, agent, ec) =>
              runEval(prims, name, body, agent, ec, { artifactKind: "memory", ci: opts.ci }));
          try {
            const evalResult = await evalFn(
              newest.primitives,
              basename(path),
              truncated,
              agentCfg,
              evalCfg,
            );
            sessFindings.push(...mapEvalToMemoryFindings(evalResult));
          } catch {
            // intentional: adherence eval is best-effort; presence + inventory still ship
            sessFindings.push(sessFinding({
              id: "sess-006",
              tier: "sessions",
              severity: "info",
              message: "Rule adherence judge failed; presence and rule inventory still reported",
              fixable: false,
            }));
          }
        } else {
          sessFindings.push(sessFinding({
            id: "sess-006",
            tier: "sessions",
            severity: "info",
            message: "Rule adherence scoring skipped — session evaluation requires an API judge",
            fixable: false,
          }));
        }
      }

      const filtered = sessFindings
        .map((finding) => stampRule(finding, finding.code!, effective))
        .filter((finding): finding is ReviewFinding => finding !== null);
      tiers.sessions = { available: true, count: loadedSess.sessions.length, findings: filtered };
    }
  }

  const all = [
    ...structTier.findings,
    ...heurTier.findings,
    ...(tiers.llm?.findings ?? []),
    ...(tiers.sessions?.findings ?? []),
  ];
  const summary = tallyFindings(all);

  return {
    path,
    origin,
    tiers,
    summary: { passed: summary.passed, warnings: summary.warnings, errors: summary.errors },
    ...(ruleWarnings.length ? { ruleWarnings } : {}),
  };
}

