tool_input.new_string:
async function reviewCwdMemory(cwd: string, opts: ReviewOptions): Promise<ReviewResult[]> {
  const out: ReviewResult[] = [];
  for (const name of MEMORY_FILE_NAMES) {
    const file = resolvePath(cwd, name);
    if (existsSync(file)) out.push(await reviewMemoryFile(file, opts));
  }
  return out;
}

/** Public Review interface: one path in, one list out. */
export async function review(path: string, opts: ReviewOptions = {}): Promise<ReviewResult[]> {
  if (isSkillDir(path)) {
    return [await reviewSkill(path, opts), ...(await reviewCwdMemory(opts.cwd ?? process.cwd(), opts))];
  }
  return [await reviewMemoryFile(path, opts)];
}

