/** Public Review interface: one path in, one list out. */
export async function review(path: string, opts: ReviewOptions = {}): Promise<ReviewResult[]> {
  const cwd = opts.cwd ?? process.cwd();
  let results: ReviewResult[];
  if (isSkillDir(path)) {
    results = [await reviewSkill(path, opts), ...(await reviewCwdMemory(cwd, opts))];
  } else {
    const isMemory =
      existsSync(path) && statSync(path).isFile() && MEMORY_FILE_NAMES.has(basename(path));
    results = isMemory
      ? [await reviewMemoryFile(path, opts)]
      : [...(await reviewAll(path, opts)), ...(await reviewCwdMemory(cwd, opts))];
  }
  return results.sort((a, b) => a.path.localeCompare(b.path));
}

