    const expand = hasIssues || !!opts.verbose;

    const countLabel = errCount > 0
      ? pc.red(`${errCount} error${errCount === 1 ? "" : "s"}`)
      : warnCount > 0
      ? pc.yellow(`${warnCount} warning${warnCount === 1 ? "" : "s"}`)
