          ...(parseRule?.docUrl ? { docUrl: parseRule.docUrl } : {}),
        })]
      : [],
    warnings: [],
  });
  continue;
}

const description = [
  String(loaded.model.data["description"] ?? ""),
  String(loaded.model.data["when_to_use"] ?? ""),
]
  .filter((s) => s.trim())
  .join(" ");
