/** Exact-path redirects (Blume has no wildcards). One `from` per path; dual slash variants collide. */
function redirs(pairs: Array<[string, string]>) {
  return pairs.map(([from, to]) => ({
    from: from.replace(/\/$/, "") || "/",
    to: to === "/" ? "/" : to.endsWith("/") ? to : `${to}/`,
    status: 301 as const,
  }));
10→}

